package com.motojet.takip;

import android.app.*;
import android.os.Bundle;
import android.content.*;
import android.database.Cursor;
import android.database.sqlite.*;
import android.graphics.Color;
import android.view.*;
import android.widget.*;
import java.text.*;
import java.util.*;

public class MainActivity extends Activity {
    SQLiteDatabase db; LinearLayout root; EditText name, date, first, combined, start, end, breakMinutes; Spinner type; TextView report;
    final String[] types={"Kendi motoru","Kendi arabası","Şirket motoru"};
    final int[] defaultsFirst={85,95,65}, defaultsCombined={60,70,42};
    android.content.SharedPreferences prefs;
    @Override public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("rates",MODE_PRIVATE); db=openOrCreateDatabase("motojet.db",MODE_PRIVATE,null);db.execSQL("CREATE TABLE IF NOT EXISTS shifts(id INTEGER PRIMARY KEY AUTOINCREMENT, courier TEXT NOT NULL, day TEXT NOT NULL, vehicle TEXT NOT NULL, first_count INTEGER, combined_count INTEGER, first_rate REAL, combined_rate REAL, start_time TEXT, end_time TEXT, break_mins INTEGER, minutes INTEGER, earning REAL)"); showMain();}
    TextView label(String s){TextView t=new TextView(this);t.setText(s);t.setTextColor(Color.rgb(30,45,65));t.setTextSize(15);t.setPadding(0,12,0,4);return t;}
    EditText field(String hint,String value,boolean numeric){EditText e=new EditText(this);e.setSingleLine(true);e.setHint(hint);e.setText(value);if(numeric)e.setInputType(2);root.addView(e);return e;}
    void button(String title,Runnable action){Button b=new Button(this);b.setText(title);b.setOnClickListener(v->action.run());root.addView(b);}
    void init(String title){ScrollView sc=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(26,22,26,32);root.setBackgroundColor(Color.rgb(247,249,252));sc.addView(root);setContentView(sc);TextView h=label(title);h.setTextSize(24);h.setTextColor(Color.rgb(17,56,104));root.addView(h);}
    String val(EditText e){return e.getText().toString().trim();}
    int number(EditText e){try{return Integer.parseInt(val(e));}catch(Exception ex){return 0;}}
    double rate(int i,boolean isFirst){return prefs.getFloat((isFirst?"f":"c")+i,isFirst?defaultsFirst[i]:defaultsCombined[i]);}
    void showMain(){init("MotoJet | Kurye Takip");root.addView(label("Günlük paket, kazanç ve mesai yönetimi"));name=field("Kurye adı", "",false);date=field("Tarih (YYYY-AA-GG)",new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date()),false);root.addView(label("Araç türü"));type=new Spinner(this);type.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,types));root.addView(type);first=field("İlk paket sayısı","0",true);combined=field("Birleşen paket sayısı","0",true);start=field("Başlangıç (09:00)","09:00",false);end=field("Bitiş (18:00)","18:00",false);breakMinutes=field("Mola (dakika)","0",true);button("KAYDET VE HESAPLA",()->save());button("KAYITLARI VE TOPLAMLARI GÖR",()->showHistory());button("PAKET ÜCRETLERİNİ DÜZENLE",()->showRates());report=label("");root.addView(report);}
    int parseTime(String s){if(!s.matches("\\d{2}:\\d{2}"))throw new IllegalArgumentException("Saat HH:MM olmalı");String[] a=s.split(":");int h=Integer.parseInt(a[0]),m=Integer.parseInt(a[1]);if(h>23||m>59)throw new IllegalArgumentException("Geçersiz saat");return h*60+m;}
    void save(){try{String courier=val(name),day=val(date);if(courier.isEmpty())throw new IllegalArgumentException("Kurye adı gerekli");SimpleDateFormat df=new SimpleDateFormat("yyyy-MM-dd",Locale.US);df.setLenient(false);if(!df.format(df.parse(day)).equals(day))throw new Exception();int a=number(first),b=number(combined),br=number(breakMinutes);if(a<0||b<0||br<0)throw new IllegalArgumentException("Negatif değer olamaz");int minutes=parseTime(val(end))-parseTime(val(start));if(minutes<0)minutes+=1440;minutes-=br;if(minutes<0)throw new IllegalArgumentException("Mola süresi mesaiyi aşıyor");int i=type.getSelectedItemPosition();double fr=rate(i,true),cr=rate(i,false),total=a*fr+b*cr;ContentValues cv=new ContentValues();cv.put("courier",courier);cv.put("day",day);cv.put("vehicle",types[i]);cv.put("first_count",a);cv.put("combined_count",b);cv.put("first_rate",fr);cv.put("combined_rate",cr);cv.put("start_time",val(start));cv.put("end_time",val(end));cv.put("break_mins",br);cv.put("minutes",minutes);cv.put("earning",total);db.insertOrThrow("shifts",null,cv);report.setText(String.format(new Locale("tr","TR"),"Kaydedildi! %d paket | %.2f TL | %d sa %d dk | Saatlik %.2f TL",a+b,total,minutes/60,minutes%60,minutes==0?0:total*60/minutes));Toast.makeText(this,"Kayıt kaydedildi",Toast.LENGTH_SHORT).show();}catch(Exception ex){new AlertDialog.Builder(this).setMessage("Bilgileri kontrol et: "+ex.getMessage()).setPositiveButton("Tamam",null).show();}}
    void showRates(){init("Paket ücretleri (TL)");EditText[] f=new EditText[3],c=new EditText[3];for(int i=0;i<3;i++){root.addView(label(types[i]));f[i]=field("İlk paket",String.valueOf(rate(i,true)),false);f[i].setInputType(8194);c[i]=field("Birleşen",String.valueOf(rate(i,false)),false);c[i].setInputType(8194);}button("ÜCRETLERİ KAYDET",()->{try{android.content.SharedPreferences.Editor ed=prefs.edit();for(int i=0;i<3;i++){float a=Float.parseFloat(val(f[i]).replace(',','.')),b=Float.parseFloat(val(c[i]).replace(',','.'));if(a<0||b<0)throw new Exception();ed.putFloat("f"+i,a);ed.putFloat("c"+i,b);}ed.apply();showMain();}catch(Exception e){Toast.makeText(this,"Geçerli pozitif ücret gir",Toast.LENGTH_LONG).show();}});button("GERİ",()->showMain());}
    void showHistory(){init("Kayıtlar ve rapor");Cursor sum=db.rawQuery("SELECT COUNT(*),COALESCE(SUM(first_count+combined_count),0),COALESCE(SUM(earning),0),COALESCE(SUM(minutes),0) FROM shifts",null);if(sum.moveToFirst())root.addView(label(String.format(new Locale("tr","TR"),"%d kayıt | %d paket | %.2f TL | %d saat %d dk",sum.getInt(0),sum.getInt(1),sum.getDouble(2),sum.getInt(3)/60,sum.getInt(3)%60)));sum.close();Cursor cur=db.rawQuery("SELECT id,courier,day,vehicle,first_count,combined_count,minutes,earning FROM shifts ORDER BY day DESC,id DESC LIMIT 300",null);while(cur.moveToNext()){final int id=cur.getInt(0);String line=String.format(new Locale("tr","TR"),"%s | %s\n%s\nİlk: %d, Birleşen: %d | %d sa %d dk\nKazanç: %.2f TL",cur.getString(2),cur.getString(1),cur.getString(3),cur.getInt(4),cur.getInt(5),cur.getInt(6)/60,cur.getInt(6)%60,cur.getDouble(7));TextView t=label(line);t.setPadding(8,18,8,18);root.addView(t);Button del=new Button(this);del.setText("Bu kaydı sil (#"+id+")");del.setOnClickListener(v->new AlertDialog.Builder(this).setMessage("Bu kayıt silinsin mi?").setNegativeButton("Vazgeç",null).setPositiveButton("Sil",(d,w)->{db.delete("shifts","id=?",new String[]{String.valueOf(id)});showHistory();}).show());root.addView(del);}cur.close();button("GERİ",()->showMain());}
    @Override public void onBackPressed(){showMain();}
    @Override protected void onDestroy(){if(db!=null&&db.isOpen())db.close();super.onDestroy();}
}
